# initialize_parameters ----
## Setup ----
# `small_parameters` is in helper-small-parameters.R.

## IO correctness ----
test_that("`initialize_parameters()` works with correct inputs", {
  parameters <- small_parameters |>
    add_priors(
      log_q ~ normal(mean = log(0.5), sd = 0.2),
      module_name = "Fleet",
      fleet = "survey1"
    )
  parameter_table <- FIMS:::initialize_parameters(
    parameters
  )[["parameter_table"]]
  #' @description Test that `initialize_parameters()` names prior rows apart from a process's own parameters.
  expect_setequal(
    object = parameter_table[["name"]][
      parameter_table[["distribution_type"]] %in% "prior"
    ],
    expected = c(
      "Fleet.survey1.log_q_prior_expected_mean",
      "Fleet.survey1.log_q_prior_log_sd"
    )
  )
})

## Edge handling ----
# No edge cases to test.

## Error handling ----
test_that("`initialize_parameters()` returns correct error messages", {
  shared_parameters <- small_parameters |>
    dplyr::mutate(
      value = dplyr::if_else(label == "log_Fmort", -(1:7) / 2, value),
      map_group = dplyr::if_else(label == "log_Fmort", 1L, NA_integer_)
    )
  #' @description Test that `initialize_parameters()` errors when rows that share 1 estimate start from different values.
  expect_error(
    object = FIMS:::initialize_parameters(shared_parameters),
    regexp = "identical starting"
  )
  unsorted_parameters <- small_parameters |>
    dplyr::arrange(dplyr::desc(timing))
  #' @description Test that `initialize_parameters()` errors for rows out of year order, because FIMS reads values in row order and sorting would change the model.
  expect_error(
    object = FIMS:::initialize_parameters(unsorted_parameters),
    regexp = "not in year and age order"
  )
})

# map_levels ----
## Setup ----
